// プロジェクトマネジメント入門の中身。仕組みは app.js（全サイト共通）。
// 本文は概念の理解が目的なので、式は使わず、言葉・図・具体例で説明する。必要な式は mathbox（折りたたみ）に入れる。
// sections は [見出し, HTML] の配列。quiz は [問い, 選択肢, 正解の番号, 解説]。labs は実験（app.js の説明を参照）。
const table=(heads,rows)=>`<div class="tablewrap"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const note=(text)=>`<div class="note">${text}</div>`;
const flow=(items)=>`<div class="flow">${items.map((x,i)=>`${i?'<span class="connector" aria-hidden="true">→</span>':''}<div class="node ${i===items.length-1?'dark':''}">${x}</div>`).join('')}</div>`;
const tree=(root,kids)=>`<div class="tree"><div class="tree-root">${root}</div><div class="tree-kids">${kids.map(k=>`<div class="tree-kid"><b>${k[0]}</b>${k[1]?`<ul>${k[1].map(x=>`<li>${x}</li>`).join('')}</ul>`:''}</div>`).join('')}</div></div>`;
const mathbox=(body,label='計算のしかたを見る')=>`<details class="mathbox"><summary>${label}（読まなくても先に進めます）</summary>${body}</details>`;

